python3 -c 'import os,time,json,math;P=os.getenv("TM_STATE","hu_tm.state");g=int(open(P).read())if os.path.exists(P)else 0;W=os.getenv("TM_WORD","1");T=os.getenv("TM_TARGET","11");S=float(os.getenv("TM_SLEEP",".2"));J=lambda x:json.dumps(x,separators=(",",":"));exec("while 1:\n hit=[]\n for p in range(g+1):\n  w=(math.isqrt(8*p+1)-1)//2;t=w*(w+1)//2;b=p-t;k=w-b+1;c=b;B=4*(k+1);q=h=0;A={i for i,x in enumerate(W)if x==\"1\"};halt=0;n=g-p+1\n  for z in range(n):\n   a=int(h in A);j=2*q+a;d=(c//pow(B,j))%B;r=d%(k+1);d//=k+1;m=d%2;d//=2;v=d%2\n   (A.add(h)if v else A.discard(h));h+=1 if m else-1;q=r\n   if q==k:halt=z+1;break\n  if halt==n and \"\".join(\"1\"if i in A else\"0\"for i in range(len(T)))==T:hit.append({\"program\":p,\"states\":k,\"code\":c,\"steps\":halt})\n open(P,\"w\").write(str(g+1));print(J({\"protocol\":\"HU-AUTO-UTM/1.0\",\"generation\":g,\"input\":W,\"target\":T,\"solutions\":hit,\"model\":\"binary single-tape TM; Cantor-enumerated transition tables; diagonal dovetailing\",\"claims\":{\"host_shell_exec\":0,\"global_halting_decider\":0,\"global_arithmetic_complete\":0,\"self_awareness\":0}}),flush=True);g+=1;time.sleep(S)")' 